use serde_json::{json,Value};use sha2::{Sha256,Digest};use std::{fs,path::Path,collections::BTreeMap,process::Command,fmt::Write};
use rustc_demangle::demangle;
const R:&str="/home/ubuntu/src/zopro-perf-work/swiss-control-audit175";
const P:&str="/home/ubuntu/src/zopro-perf-work/swiss-groups-sdk175";
fn hash(b:&[u8])->String{format!("{:x}",Sha256::digest(b))}
fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
#[derive(Clone)]struct Symbol{raw:String,pretty:String,address:u64,size:u64,bytes:Vec<u8>}
fn u16at(b:&[u8],i:usize)->u16{u16::from_le_bytes(b[i..i+2].try_into().unwrap())}
fn u64at(b:&[u8],i:usize)->u64{u64::from_le_bytes(b[i..i+8].try_into().unwrap())}
fn symbols(path:&str)->BTreeMap<String,Vec<Symbol>>{let bytes=fs::read(path).unwrap();assert_eq!(&bytes[..6],b"\x7fELF\x02\x01");assert_eq!(u16at(&bytes,18),62);let shoff=u64at(&bytes,40)as usize;let step=u16at(&bytes,58)as usize;assert_eq!(step,64);let count=u16at(&bytes,60)as usize;let mut exec=vec![];for n in 0..count{let at=shoff+n*step;let flags=u64at(&bytes,at+8);if flags&4!=0{exec.push((u64at(&bytes,at+16),u64at(&bytes,at+24),u64at(&bytes,at+32)));}}
let nm=Command::new("nm").args(["-S","--defined-only",path]).output().unwrap();assert!(nm.status.success());let mut out=BTreeMap::<String,Vec<Symbol>>::new();for line in String::from_utf8(nm.stdout).unwrap().lines(){let f=line.split_whitespace().collect::<Vec<_>>();if f.len()!=4||!["t","T","w","W"].contains(&f[2]){continue;}let address=u64::from_str_radix(f[0],16).unwrap();let size=u64::from_str_radix(f[1],16).unwrap();if size==0{continue;}let Some(&(addr,off,_))=exec.iter().find(|&&(addr,_,sz)|address>=addr&&address.checked_add(size).unwrap()<=addr+sz)else{continue};let start=(off+address-addr)as usize;let raw=f[3].to_string();let pretty=format!("{:#}",demangle(&raw));out.entry(pretty.clone()).or_default().push(Symbol{raw,pretty,address,size,bytes:bytes[start..start+size as usize].to_vec()});}out}
fn class(s:&str)->&'static str{if s.contains("g2_borrowed::apply"){"G2_stream"}else if s.contains("stream_g1_impl"){"G1_stream"}else if s.contains("msm_affine::grouping::scalar_groups"){"grouping"}else if s.contains("reduce_layer")&&s.contains("G2Config"){"G2_tree"}else if s.contains("reduce_layer")&&s.contains("G1Config"){"G1_tree"}else if s.contains("inverse::inverse")&&s.contains("FqConfig"){"Fq_inverse"}else{"other"}}
fn main(){let root=Path::new(R);assert!(!root.join("analysis.json").exists());let source=read(format!("{P}/analysis.json"));assert_eq!(source["gate_passed"],false);let ids=read(format!("{P}/identities.json"));let mut all=BTreeMap::new();let mut pins=BTreeMap::new();for v in["accepted","OFF","ON"]{let p=ids[v]["binary"].as_str().unwrap();assert_eq!(hash(&fs::read(p).unwrap()),ids[v]["sha256"]);pins.insert(p.to_string(),hash(&fs::read(p).unwrap()));all.insert(v,symbols(p));}
let mut rows=vec![];let mut count=0;let mut equal=0;for(name,a)in &all["accepted"]{if a.len()!=1{continue;}if let Some(b)=all["OFF"].get(name).filter(|b|b.len()==1){count+=1;if a[0].bytes==b[0].bytes{equal+=1;}}if class(name)=="other"{continue;}if a.len()!=1{continue;}let a=&a[0];let mut comparisons=BTreeMap::new();for v in["OFF","ON"]{if let Some(b)=all[v].get(name).filter(|b|b.len()==1){let b=&b[0];let byte_equal=a.bytes==b.bytes;let row=json!({"size":b.size,"address":format!("{:x}",b.address),"bytes_sha256":hash(&b.bytes),"byte_identical_to_accepted":byte_equal,"raw_symbol":b.raw});comparisons.insert(v,row);let asm=Command::new("objdump").args(["-d","--no-show-raw-insn"]).arg(format!("--disassemble={}",b.raw)).arg(ids[v]["binary"].as_str().unwrap()).output().unwrap();assert!(asm.status.success());fs::write(root.join(format!("{count}-{v}.asm")),asm.stdout).unwrap();}}
rows.push(json!({"name":a.pretty,"class":class(&a.pretty),"accepted_size":a.size,"accepted_address":format!("{:x}",a.address),"accepted_bytes_sha256":hash(&a.bytes),"comparisons":comparisons}));}
let mut profiles=BTreeMap::new();for (n,p)in source["diagnostics"]["profiles"].as_object().unwrap(){let mut categories=BTreeMap::<String,(u64,u64)>::new();for s in p["symbols"].as_array().unwrap(){let pretty=format!("{:#}",demangle(s["symbol"].as_str().unwrap()));let c=class(&pretty);let row=categories.entry(c.into()).or_default();row.0+=s["period"].as_u64().unwrap();row.1+=s["samples"].as_u64().unwrap();}profiles.insert(n,json!({"total_period":p["period"],"total_samples":p["samples"],"categories":categories.iter().map(|(c,(period,samples))|(c.clone(),json!({"period":period,"samples":samples,"share":*period as f64/p["period"].as_f64().unwrap()}))).collect::<BTreeMap<_,_>>()}));}
let data=json!({"raw_ELF_bytes_not_relocation_normalized":true,"common_unique_code_symbols":count,"byte_identical_code_symbols":equal,"selected":rows,"profiles":profiles,"no_new_capture":true,"new_SDK_requests":0,"new_proofs":0,"proof_ledger":21007,"closed_trial_gate_unchanged":false,"production_changed":false});fs::write(root.join("analysis.json"),serde_json::to_vec_pretty(&data).unwrap()).unwrap();for f in["audit.rs","audit"]{let p=root.join(f);pins.insert(p.display().to_string(),hash(&fs::read(p).unwrap()));}let p=format!("{P}/analysis.json");pins.insert(p.clone(),hash(&fs::read(p).unwrap()));fs::write(root.join("pins.json"),serde_json::to_vec_pretty(&pins).unwrap()).unwrap();println!("Commonunique symbols {count}, rawbyteidentical {equal}");for row in data["selected"].as_array().unwrap(){println!("{} {} OFF={} ON={} Abytes={}",row["class"],row["name"],row["comparisons"]["OFF"]["byte_identical_to_accepted"],row["comparisons"]["ON"]["byte_identical_to_accepted"],row["accepted_size"]);}
}
